import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

import { create } from 'qrcode';

import { TICKET_TOKEN } from './door';

/** The video Chromium plays back as the camera. Generated by camera.setup.e2e.ts; git-ignored. */
export const FAKE_CAMERA_VIDEO = join(__dirname, '..', '.fixtures', 'ticket-qr.y4m');

const WIDTH = 640;
const HEIGHT = 480;
const MODULE_PX = 12;
const QUIET_ZONE_MODULES = 4;
const FRAMES = 5;

/**
 * Writes a raw YUV4MPEG2 video of `token` as a QR code on white, the format Chromium's
 * `--use-file-for-fake-video-capture` reads. It is uncompressed, so writing it by hand needs
 * no encoder (the ffmpeg Playwright ships only encodes VP8).
 */
export function writeQrVideo(path: string = FAKE_CAMERA_VIDEO, token: string = TICKET_TOKEN): void {
  const { modules } = create(token, { errorCorrectionLevel: 'M' });
  const size = modules.size;
  const symbol = (size + QUIET_ZONE_MODULES * 2) * MODULE_PX;
  const left = Math.floor((WIDTH - symbol) / 2);
  const top = Math.floor((HEIGHT - symbol) / 2);

  const luma = Buffer.alloc(WIDTH * HEIGHT, 235); // white
  for (let y = 0; y < HEIGHT; y += 1) {
    for (let x = 0; x < WIDTH; x += 1) {
      const row = Math.floor((y - top) / MODULE_PX) - QUIET_ZONE_MODULES;
      const column = Math.floor((x - left) / MODULE_PX) - QUIET_ZONE_MODULES;
      const inside = row >= 0 && column >= 0 && row < size && column < size;
      if (inside && modules.get(row, column) === 1) luma[y * WIDTH + x] = 16; // black
    }
  }
  const chroma = Buffer.alloc((WIDTH / 2) * (HEIGHT / 2), 128); // neutral: grey scale only

  const header = Buffer.from(`YUV4MPEG2 W${WIDTH} H${HEIGHT} F5:1 Ip A1:1\n`);
  const frame = Buffer.concat([Buffer.from('FRAME\n'), luma, chroma, chroma]);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, Buffer.concat([header, ...Array.from({ length: FRAMES }, () => frame)]));
}
